func:
// Genesis gebruikt zero-based adressen in Modbus-berichten.
// Nieuwere firmware: 30159 = positie 158, direct verbruikt vermogen.
// Oudere firmware: 30079..30081 = posities 78..80, externe meter per fase.
// 40023/40024 = holding-registerposities 22/23, tapwater start/stop.
const unitid = Number(env.get('THERMIA_UNIT_ID') || 1);
const source = String(env.get('THERMIA_POWER_SOURCE') || 'unit').toLowerCase();
const power = source === 'meter' ? {
    topic: 'thermia.power.meter',
    payload: { fc: 4, unitid, address: 78, quantity: 3 }
} : {
    topic: 'thermia.power.unit',
    payload: { fc: 4, unitid, address: 158, quantity: 1 }
};
const settings = {
    topic: 'thermia.settings',
    payload: { fc: 3, unitid, address: 22, quantity: 2 }
};
return [[power, settings], { topic: 'thermia.price.tick', payload: Date.now() }];

function registers(m) {
    if (Array.isArray(m.payload)) return m.payload;
    if (m.payload && Array.isArray(m.payload.data)) return m.payload.data;
    if (m.responseBuffer && Array.isArray(m.responseBuffer.data)) return m.responseBuffer.data;
    if (m.modbusResponse && Array.isArray(m.modbusResponse.data)) return m.modbusResponse.data;
    return [];
}
function int16(v) {
    v = Number(v) & 0xffff;
    return v > 0x7fff ? v - 0x10000 : v;
}
const data = registers(msg);
if (msg.topic === 'thermia.power.unit') {
    if (!data.length) {
        node.error('Geen data voor register 30159 ontvangen', msg);
        return [null, null];
    }
    // Registereenheid is 0,01 kW: raw * 10 = W.
    const power = Math.max(0, int16(data[0]) * 10);
    node.status({ fill: 'green', shape: 'dot', text: power.toFixed(0) + ' W (unit)' });
    return [{ payload: { Connected: 1, 'Ac/Power': power } }, null];
}
if (msg.topic === 'thermia.power.meter') {
    if (data.length < 3) {
        node.error('Geen data voor registers 30079..30081 ontvangen', msg);
        return [null, null];
    }
    const phases = data.slice(0, 3).map((v) => Math.max(0, int16(v)));
    const power = phases.reduce((sum, value) => sum + value, 0);
    node.status({ fill: 'green', shape: 'dot', text: power.toFixed(0) + ' W (meter)' });
    return [{ payload: {
        Connected: 1,
        'Ac/Power': power,
        'Ac/L1/Power': phases[0],
        'Ac/L2/Power': phases[1],
        'Ac/L3/Power': phases[2]
    } }, null];
}
if (msg.topic === 'thermia.settings') {
    if (data.length < 2) {
        node.error('Geen data voor registers 40023/40024 ontvangen', msg);
        return [null, null];
    }
    return [null, {
        topic: 'thermia.settings',
        payload: {
            startC: int16(data[0]) / 100,
            stopC: int16(data[1]) / 100,
            readAt: Date.now()
        }
    }];
}
return [null, null];

const cheapestCount = Math.max(1, Math.min(24, Number(env.get('THERMIA_CHEAPEST_HOURS') || 5)));
const maxAgeMin = Math.max(5, Number(env.get('THERMIA_PRICE_MAX_AGE_MIN') || 90));
const now = new Date();

function numeric(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}
function fromDess(dess) {
    const prices = dess && dess.output && dess.output.p_b;
    if (!prices) return [];
    return Object.keys(prices).map((key) => {
        const hour = Number(key) % 24;
        const start = new Date(now);
        start.setHours(hour, 0, 0, 0);
        return { start: start.getTime(), hour, price: numeric(prices[key]) };
    }).filter((p) => p.price !== null && p.start >= new Date(now).setHours(0, 0, 0, 0) && p.start < new Date(now).setHours(24, 0, 0, 0));
}
function normalize(input) {
    if (!input) return [];
    if (input.output && input.output.p_b) return fromDess(input);
    if (input.dess) return fromDess(input.dess);
    if (input.records && Array.isArray(input.records.deGs)) {
        return input.records.deGs.map((p) => ({ start: Number(p[0]), price: numeric(p[1]) }));
    }
    const list = Array.isArray(input) ? input : (input.prices || input.values || []);
    return list.map((p, i) => {
        if (typeof p === 'number') {
            const start = new Date(now);
            start.setHours(i, 0, 0, 0);
            return { start: start.getTime(), price: p };
        }
        const rawStart = p.start ?? p.startTime ?? p.timestamp ?? p.time;
        let start = typeof rawStart === 'number' ? rawStart : Date.parse(rawStart);
        if (start > 0 && start < 100000000000) start *= 1000;
        return { start, price: numeric(p.price ?? p.value ?? p.buyPrice) };
    });
}

let incoming = msg.topic !== 'thermia.price.tick' ? msg.payload : null;
if (incoming) {
    global.set('thermiaPrices', incoming);
    global.set('thermiaPricesReceivedAt', Date.now());
}
const source = incoming || global.get('thermiaPrices') || global.get('thermiaDess') || global.get('dess');
const receivedAt = Number(global.get('thermiaPricesReceivedAt') || Date.now());
let prices = normalize(source).filter((p) => Number.isFinite(p.start) && p.price !== null);
const dayStart = new Date(now); dayStart.setHours(0, 0, 0, 0);
const dayEnd = new Date(dayStart); dayEnd.setDate(dayEnd.getDate() + 1);
prices = prices.filter((p) => p.start >= dayStart.getTime() && p.start < dayEnd.getTime());

if (prices.length < cheapestCount || Date.now() - receivedAt > maxAgeMin * 60000) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'geen verse volledige prijsreeks' });
    return { topic: 'thermia.price.state', payload: { valid: false, cheap: false, evaluatedAt: Date.now() } };
}
const cheapest = prices.slice().sort((a, b) => a.price - b.price || a.start - b.start).slice(0, cheapestCount);
const current = prices.find((p) => now.getTime() >= p.start && now.getTime() < p.start + 3600000);
const cheap = Boolean(current && cheapest.some((p) => p.start === current.start));
const hours = cheapest.map((p) => new Date(p.start).getHours()).sort((a, b) => a - b);
node.status({ fill: cheap ? 'green' : 'blue', shape: 'dot', text: (cheap ? 'goedkoop uur; ' : 'normaal; ') + hours.join(', ') });
return {
    topic: 'thermia.price.state',
    payload: {
        valid: true,
        cheap,
        currentPrice: current ? current.price : null,
        cheapestHours: hours,
        evaluatedAt: Date.now()
    }
};

function envNumber(name) {
    const raw = env.get(name);
    if (raw === undefined || raw === null || raw === '') return null;
    const value = Number(raw);
    return Number.isFinite(value) ? value : null;
}
const enabled = String(env.get('THERMIA_ENABLE_WRITES') || 'false').toLowerCase() === 'true';
const delta = envNumber('THERMIA_CHEAP_DELTA_C') ?? 3;
const maxC = envNumber('THERMIA_MAX_TAPWATER_C') ?? 60;
const unitid = Number(env.get('THERMIA_UNIT_ID') || 1);
let baseStart = envNumber('THERMIA_TAPWATER_START_C');
let baseStop = envNumber('THERMIA_TAPWATER_STOP_C');

if (msg.topic === 'thermia.price.state') {
    context.set('priceState', msg.payload);
    return null;
}
if (msg.topic !== 'thermia.settings') return null;
const actual = msg.payload;
const price = context.get('priceState') || { valid: false, cheap: false };

// Zonder expliciete basiswaarden leren we alleen tijdens een aantoonbaar niet-goedkoop uur.
if ((baseStart === null || baseStop === null) && price.valid && !price.cheap) {
    context.set('learnedStart', actual.startC);
    context.set('learnedStop', actual.stopC);
}
baseStart = baseStart ?? context.get('learnedStart');
baseStop = baseStop ?? context.get('learnedStop');

if (!enabled) {
    node.status({ fill: 'grey', shape: 'ring', text: 'alleen lezen; schrijven uit' });
    return null;
}
if (!Number.isFinite(baseStart) || !Number.isFinite(baseStop)) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'normale start/stop nog onbekend' });
    return null;
}
if (baseStart < 20 || baseStop < baseStart || baseStop > maxC || delta < 0 || delta > 10) {
    node.error('Onveilige Thermia-configuratie: controleer start/stop, delta en maximum', msg);
    return null;
}
const boost = price.valid && price.cheap ? delta : 0;
const targetStart = Math.min(maxC, baseStart + boost);
const targetStop = Math.min(maxC, baseStop + boost);
if (targetStop < targetStart) {
    node.error('Berekende stoptemperatuur ligt onder starttemperatuur', msg);
    return null;
}
const same = Math.abs(actual.startC - targetStart) < 0.005 && Math.abs(actual.stopC - targetStop) < 0.005;
if (same) {
    node.status({ fill: boost ? 'green' : 'blue', shape: 'dot', text: boost ? '+' + boost + ' °C actief' : 'normale waarden actief' });
    return null;
}
const lastWrite = Number(context.get('lastWrite') || 0);
if (Date.now() - lastWrite < 60000) return null;
context.set('lastWrite', Date.now());
node.status({ fill: 'yellow', shape: 'dot', text: 'schrijf ' + targetStart + '/' + targetStop + ' °C' });
return {
    topic: 'thermia.write.tapwater',
    payload: {
        value: [Math.round(targetStart * 100), Math.round(targetStop * 100)],
        fc: 16,
        unitid,
        address: 22,
        quantity: 2
    }
};
